```go
func (f *Funcs) Pick(args ...interface{}) (map[string]interface{}, error) {
	if len(args) <= 1 {
		return nil, fmt.Errorf("wrong number of args: wanted 2 or more, got %d", len(args))
	}
	m, ok := args[len(args)-1].(map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("wrong map type: must be map[string]any, got %T", args[len(args)-1])
	}
	keys := args[:len(args)-1]
	if len(keys) == 1 {
		if l, ok := keys[0].([]interface{}); ok {
			keys = l
		}
	}
	picked := map[string]interface{}{}
	for _, k := range keys {
		key, ok := k.(string)
		if !ok {
			return nil, fmt.Errorf("wrong key type: must be string, got %T (%v)", k, k)
		}
		if v, ok := m[key]; ok {
			picked[key] = v
		}
	}
	return picked, nil
}
```

